// V-Node Table (Shared, persistent file metadata)
struct Vnode {
    int inode_num;
    int ref_count;    // Count of FileTableEntries pointing here
};

// File Table (Shared, describes one open instance)
struct FileTableEntry {
    off_t offset;         // Current position (non-shared across FTEs)
    int access_flags;     // O_RDONLY, O_WRONLY, etc.
    struct Vnode* vn_ptr; // Points to shared metadata
};

// Descriptor Table (Per-Process)
struct ProcDescriptor {
    struct FileTableEntry* fd_array[MAX_FDS];
};

// Sharing Examples:
// 1. Same FTE, Different FDs (via dup/fork): Two FDs point to the same offset.
// 2. Different FTEs, Same Vnode: Two processes have separate offsets accessing the same file data.
